<template><div class="page"><h2>FMECA 管理</h2><p class="intro">面向动力和电源典型系统维护故障模式、原因及风险等级。首次进入且知识库为空时会载入测试样例，点击“保存全部”后写入知识库。</p><el-alert v-if="sampleLoaded" title="当前显示项目测试样例，尚未保存到知识库" type="info" :closable="false"/><div class="actions"><el-button type="primary" @click="add">新增记录</el-button><el-button @click="loadSample">重新生成测试样例</el-button><el-button type="success" :loading="saving" @click="save">保存全部</el-button></div><el-table :data="rows" style="margin-top:16px"><el-table-column label="部件"><template #default="s"><el-input v-model="s.row.component"/></template></el-table-column><el-table-column label="故障模式"><template #default="s"><el-input v-model="s.row.mode"/></template></el-table-column><el-table-column label="原因"><template #default="s"><el-input v-model="s.row.cause"/></template></el-table-column><el-table-column label="风险" width="150"><template #default="s"><el-select v-model="s.row.level"><el-option label="高" value="高"/><el-option label="中" value="中"/><el-option label="低" value="低"/></el-select></template></el-table-column><el-table-column label="操作" width="100"><template #default="s"><el-button link type="danger" @click="rows.splice(s.$index,1)">删除</el-button></template></el-table-column></el-table></div></template>
<script setup>import{ref,onMounted}from'vue';import{ElMessage}from'element-plus';const rows=ref([]),recordId=ref(null),saving=ref(false),sampleLoaded=ref(false);const sample=()=>[{component:'液氧涡轮泵',mode:'泵效率下降',cause:'轴承磨损、叶轮间隙增大或入口气蚀',level:'高'},{component:'推进剂供应管路',mode:'推进剂泄漏',cause:'密封件老化、管路裂纹或接头松动',level:'高'},{component:'燃烧室',mode:'温度异常升高',cause:'混合比偏差、冷却通道堵塞或燃烧不稳定',level:'高'},{component:'蓄电池组',mode:'容量衰减',cause:'循环老化、单体不一致或低温性能下降',level:'中'},{component:'配电单元',mode:'母线欠压',cause:'接触电阻增大、负载突变或稳压模块异常',level:'高'},{component:'姿态控制执行机构',mode:'执行器迟滞',cause:'机械卡滞、驱动电流异常或控制链路延迟',level:'中'}];async function load(){const r=await fetch(`/api/v1/knowledge/fmeca/?_=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw Error('FMECA加载失败');const d=await r.json();const latest=d[0];if(latest&&Array.isArray(latest.data)&&latest.data.length){recordId.value=latest.id;rows.value=latest.data;sampleLoaded.value=false}else loadSample()}function loadSample(){rows.value=sample();sampleLoaded.value=true}function add(){rows.value.push({component:'',mode:'',cause:'',level:'中'});sampleLoaded.value=false}async function save(){if(!rows.value.length)return ElMessage.warning('请至少保留一条FMECA记录');saving.value=true;try{const url=recordId.value?`/api/v1/knowledge/fmeca/${recordId.value}/`:'/api/v1/knowledge/fmeca/';const r=await fetch(url,{method:recordId.value?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:rows.value})});const d=await r.json();if(!r.ok)throw Error(d.detail||d.error||'保存失败');recordId.value=d.id;sampleLoaded.value=false;ElMessage.success(`FMECA已保存，版本 ${d.version}`)}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}onMounted(async()=>{try{await load()}catch(e){ElMessage.error(e.message);loadSample()}})</script><style scoped>.page{max-width:1300px}.intro{color:#66788f}.actions{margin-top:14px}.actions .el-button{margin-right:8px}.el-alert{margin:14px 0}</style>
